const defaults = {
    mode: 'temperature',
    tempSource: 'ruuvi3',
    temperatureProfileVersion: 3,
    sensorFailureAction: 'internal',
    setpoint: 20,
    power: 5,
    duration: 0,
    standbyVent: false,
    frostEnabled: false,
    frostTemp: 5,
    frostStop: 10,
    frostPower: 4,
    batterySource: 'victron',
    lowVoltage: 11.5,
    timers: [
        { enabled: false, at: '', fired: false },
        { enabled: false, at: '', fired: false },
        { enabled: false, at: '', fired: false }
    ]
};

let persistentStore = 'file';
let saved = {};
try {
    saved = flow.get('autotermPersistent', 'file') || {};
} catch (error) {
    persistentStore = null;
    saved = flow.get('autotermPersistent') || {};
}

let cfg = flow.get('cfg') || saved.cfg || defaults;
cfg = Object.assign({}, defaults, cfg);
if (cfg.tempSource === 'ruuvi' || Number(cfg.temperatureProfileVersion || 0) < 3) { cfg.tempSource = 'ruuvi3'; cfg.temperatureProfileVersion = 3; }
if (!Array.isArray(cfg.timers) || cfg.timers.length !== 3) cfg.timers = defaults.timers;

let st = flow.get('state') || {
    status: 'Aus',
    statusCode: 0,
    subStatus: 0,
    error: 0,
    voltage: null,
    internalTemp: null,
    externalTemp: null,
    heaterTemp: null,
    fanRpm: null,
    pumpHz: null,
    version: null,
    hours: null,
    endAt: 0,
    startedByFrost: false,
    startedBy: '–',
    maintenanceActive: false,
    maintenanceSeconds: 0,
    lastMaintenanceRun: Number(saved.lastMaintenanceRun || 0),
    lastAnnualService: Number(saved.lastAnnualService || 0),
    serialReady: false,
    sessionStatus: 'Warte auf AUTOTERM-Initialisierung',
    sessionAttempt: 0
};

const crc = bytes => {
    let value = 0xffff;
    for (const byte of bytes) {
        value ^= byte;
        for (let bit = 0; bit < 8; bit++) {
            value = (value & 1) ? (value >>> 1) ^ 0xa001 : value >>> 1;
        }
    }
    return value;
};

const packet = hex => {
    const bytes = Array.from(Buffer.from(hex, 'hex'));
    const value = crc(bytes);
    bytes.push((value >>> 8) & 0xff, value & 0xff);
    return Buffer.from(bytes);
};

const sendHex = hex => ({ topic: 'autoterm.tx', payload: packet(hex) });
const stopCommand = () => sendHex('AA03000003');
const waitMode = () => cfg.standbyVent ? '01' : '02';

const controlCommand = (update, override) => {
    const options = Object.assign({
        mode: cfg.mode,
        power: cfg.power,
        setpoint: cfg.setpoint
    }, override || {});
    const operation = update ? '02' : '01';

    if (options.mode === 'ventilation') {
        return sendHex('AA03040023FFFF09FF');
    }
    if (options.mode === 'power') {
        const level = Math.max(0, Math.min(9, Number(options.power) - 1))
            .toString(16).padStart(2, '0');
        return sendHex('AA030600' + operation + 'FFFF04FF' + waitMode() + level);
    }
    const temperature = Math.max(5, Math.min(30, Number(options.setpoint)))
        .toString(16).padStart(2, '0');
    return sendHex('AA030600' + operation + 'FFFF02' + temperature + waitMode() + 'FF');
};

const cooling = () => st.statusCode === 4 || (st.statusCode === 3 && st.subStatus === 4);
const running = () => Number(st.statusCode) > 0;
const isNumber = value => value !== null && value !== '' && typeof value !== 'undefined' && Number.isFinite(Number(value));
const HEATER_DATA_MAX_AGE = 30000;
const VICTRON_DATA_MAX_AGE = 180000;
const isFresh = (seen, now, maxAge) => Number.isFinite(Number(seen)) && now - Number(seen) >= 0 && now - Number(seen) < maxAge;

const sensor = (key, now) => {
    if (String(key).startsWith('ruuvi')) {
        const value = st.sensors && st.sensors[key];
        return {
            value: value && value.temp,
            fresh: Boolean(value) && now - value.seen < 180000,
            label: value && value.label ? String(value.label) : String(key).replace('ruuvi', 'RuuviTag ')
        };
    }
    if (key === 'external') {
        return {
            value: st.externalTemp,
            fresh: isNumber(st.externalTemp) && isFresh(st.heaterSeen, now, HEATER_DATA_MAX_AGE),
            label: 'AUTOTERM extern'
        };
    }
    return {
        value: st.internalTemp,
        fresh: isNumber(st.internalTemp) && isFresh(st.heaterSeen, now, HEATER_DATA_MAX_AGE),
        label: 'AUTOTERM intern'
    };
};

const battery = now => {
    const voltageFresh = isFresh(st.batteryVoltageSeen, now, VICTRON_DATA_MAX_AGE);
    const heaterFresh = isFresh(st.heaterSeen, now, HEATER_DATA_MAX_AGE);
    if (cfg.batterySource === 'victron' && voltageFresh && isNumber(st.batteryVoltage)) {
        return { voltage: st.batteryVoltage, soc: st.batterySoc, source: 'Victron', fresh: true };
    }
    return {
        voltage: st.voltage,
        soc: st.batterySoc,
        source: 'Heizung',
        fresh: heaterFresh && isNumber(st.voltage)
    };
};

const canStart = now => {
    if (st.serialReady !== true) return 'AUTOTERM-Initialisierung läuft';
    if (cooling()) return 'Nachlauf aktiv';
    const value = battery(now);
    if (!value.fresh || !isNumber(value.voltage)) {
        return 'Keine aktuelle Batteriespannung verfügbar';
    }
    if (Number(value.voltage) < Number(cfg.lowVoltage)) {
        return 'Batteriespannung zu niedrig';
    }
    const selected = sensor(cfg.tempSource, now);
    if (cfg.mode === 'temperature' && !selected.fresh && cfg.sensorFailureAction === 'stop') {
        return 'Temperatursensor nicht verfügbar';
    }
    return '';
};

let serial = null;

if (msg.topic === 'session' && msg.payload) {
    st.serialReady = msg.payload.ready === true;
    st.sessionStatus = String(msg.payload.status || '');
    st.sessionStage = Number(msg.payload.stage || 0);
    st.sessionAttempt = Number(msg.payload.attempt || 0);
    st.sessionLastRx = Number(msg.payload.lastRx || 0);
    if (st.serialReady && st.warning && st.warning.startsWith('AUTOTERM-Initialisierung')) {
        st.warning = '';
    }
}

if (msg.topic === 'ui') {
    const action = msg.payload || {};
    if (action.action === 'set') {
        const enumValues = {
            mode: ['temperature', 'power', 'ventilation'],
            tempSource: ['ruuvi1', 'ruuvi2', 'ruuvi3', 'internal', 'external'],
            sensorFailureAction: ['internal', 'external', 'stop'],
            batterySource: ['victron', 'heater']
        };
        const ranges = {
            setpoint: [5, 30], power: [1, 10], duration: [0, 720],
            frostTemp: [0, 12], frostStop: [5, 20], frostPower: [1, 10],
            lowVoltage: [10.5, 13]
        };
        const booleans = ['standbyVent', 'frostEnabled'];
        let valid = false;
        let value = action.value;
        if (Object.prototype.hasOwnProperty.call(enumValues, action.key)) {
            valid = enumValues[action.key].includes(value);
        } else if (Object.prototype.hasOwnProperty.call(ranges, action.key)) {
            value = Number(value);
            const limits = ranges[action.key];
            valid = Number.isFinite(value) && value >= limits[0] && value <= limits[1];
        } else if (booleans.includes(action.key)) {
            valid = typeof value === 'boolean';
        }
        if (!valid) {
            st.warning = 'Ungültige Einstellung wurde verworfen';
        } else if (st.maintenanceActive && ['mode', 'power'].includes(action.key)) {
            st.warning = 'Leistung und Betriebsart sind während des Wartungslaufs gesperrt';
        } else {
            cfg[action.key] = value;
            if (['mode', 'setpoint', 'power', 'standbyVent'].includes(action.key) && st.statusCode === 3 && !cooling()) {
                serial = controlCommand(true);
            }
        }
    } else if (action.action === 'timer') {
        const index = Number(action.index);
        const timer = action.timer;
        if (!Number.isInteger(index) || index < 0 || index >= cfg.timers.length || !timer || typeof timer !== 'object') {
            st.warning = 'Ungültiger Timer wurde verworfen';
        } else {
            cfg.timers[index] = {
                enabled: timer.enabled === true,
                at: typeof timer.at === 'string' ? timer.at.slice(0, 32) : '',
                fired: false
            };
        }
    } else if (action.action === 'start') {
        const blocked = canStart(Date.now());
        if (blocked) {
            st.warning = 'Start verhindert: ' + blocked;
        } else {
            serial = controlCommand(false);
            st.endAt = cfg.duration ? Date.now() + Number(cfg.duration) * 60000 : 0;
            st.startedByFrost = false;
            st.maintenanceActive = false;
            st.maintenanceSeconds = 0;
            st.startedBy = 'Manuell';
            st.warning = '';
        }
    } else if (action.action === 'maintenance') {
        const oldMode = cfg.mode;
        const oldPower = cfg.power;
        cfg.mode = 'power';
        cfg.power = 10;
        const blocked = canStart(Date.now());
        if (blocked) {
            cfg.mode = oldMode;
            cfg.power = oldPower;
            st.warning = 'Wartungslauf verhindert: ' + blocked;
        } else {
            serial = controlCommand(false);
            st.endAt = 0;
            st.startedByFrost = false;
            st.maintenanceActive = true;
            st.maintenanceSeconds = 0;
            st.startedBy = 'Wartungslauf';
            st.warning = 'Wartungslauf: 20 Minuten volle Leistung';
        }
    } else if (action.action === 'annualDone') {
        st.lastAnnualService = Date.now();
        st.warning = 'Jährliche Wartung als durchgeführt dokumentiert';
    } else if (action.action === 'stop' && !cooling()) {
        serial = stopCommand();
        st.endAt = 0;
        st.startedByFrost = false;
        st.maintenanceActive = false;
        st.maintenanceSeconds = 0;
    }
}

if (/^ruuvi[123]$/.test(msg.topic)) {
    st.sensors = st.sensors || {};
    st.sensors[msg.topic] = msg.payload;
    if (msg.topic === 'ruuvi1') {
        st.ruuviTemp = msg.payload.temp;
        st.ruuviSeen = msg.payload.seen;
    }
}

if (msg.topic === 'batteryVoltage') {
    st.batteryVoltage = msg.payload.value;
    st.batteryVoltageSeen = msg.payload.seen;
}
if (msg.topic === 'batterySoc') {
    st.batterySoc = msg.payload.value;
    st.batterySocSeen = msg.payload.seen;
}
if (msg.topic === 'heater') {
    Object.assign(st, msg.payload);
    st.heaterSeen = Date.now();
}

if (msg.topic === 'tick') {
    const now = Date.now();
    st.sensors = st.sensors || {};
    const selected = sensor(cfg.tempSource, now);
    let effective = selected;

    if (!selected.fresh) {
        const fallback = sensor(cfg.sensorFailureAction, now);
        if ((cfg.sensorFailureAction === 'internal' || cfg.sensorFailureAction === 'external') && fallback.fresh) {
            effective = fallback;
            st.sensorFallback = true;
            st.warning = 'Regelsensor ausgefallen – Ersatzsensor aktiv';
        } else {
            st.sensorFallback = false;
            if (running() && cfg.mode === 'temperature') {
                serial = stopCommand();
                st.warning = 'Regelsensor ausgefallen – Heizung wird gestoppt';
            }
        }
    } else {
        st.sensorFallback = false;
        if (st.warning && st.warning.startsWith('Regelsensor')) st.warning = '';
    }

    st.roomTemp = effective.value;
    st.sensorOnline = effective.fresh;
    const floorReading = sensor('ruuvi2', now);
    const frostReading = floorReading.fresh ? floorReading : effective;
    st.frostTemperature = frostReading.value;
    st.frostSensor = frostReading.label;
    st.sensorSource = cfg.tempSource;
    st.effectiveSensor = effective.label;

    const batteryValue = battery(now);
    st.protectionVoltage = batteryValue.voltage;
    st.protectionSoc = batteryValue.soc;
    st.batteryDataSource = batteryValue.source;
    st.batteryOnline = batteryValue.fresh;

    if (st.maintenanceActive) {
        if (running() && !cooling() && st.status === 'Heizen') {
            st.maintenanceSeconds = Number(st.maintenanceSeconds || 0) + 10;
        }
        if (Number(st.maintenanceSeconds) >= 1200) {
            serial = stopCommand();
            st.endAt = 0;
            st.maintenanceActive = false;
            st.maintenanceSeconds = 1200;
            st.lastMaintenanceRun = now;
            st.warning = 'Monatlicher Wartungslauf erfolgreich abgeschlossen';
        }
    }

    st.maintenanceDue = !st.lastMaintenanceRun || now - st.lastMaintenanceRun > 31 * 86400000;
    st.annualServiceDue = !st.lastAnnualService || now - st.lastAnnualService > 365 * 86400000;

    if (st.endAt && now >= st.endAt && running() && !cooling()) {
        serial = stopCommand();
        st.endAt = 0;
    }

    for (const timer of cfg.timers) {
        const at = Date.parse(timer.at);
        if (timer.enabled && !timer.fired && Number.isFinite(at) && now >= at && now - at < 60000) {
            const blocked = canStart(now);
            if (!blocked) {
                serial = controlCommand(false);
                st.startedBy = 'Timer';
                st.endAt = cfg.duration ? now + Number(cfg.duration) * 60000 : 0;
            } else {
                st.warning = 'Timerstart verhindert: ' + blocked;
            }
            timer.fired = true;
        }
    }

    if (cfg.frostEnabled && frostReading.fresh && st.statusCode === 0 && Number(frostReading.value) < Number(cfg.frostTemp)) {
        const blocked = canStart(now);
        if (!blocked) {
            serial = controlCommand(false, { mode: 'power', power: cfg.frostPower });
            st.startedByFrost = true;
            st.startedBy = 'Frostschutz';
            st.endAt = 0;
        } else {
            st.warning = 'Froststart verhindert: ' + blocked;
        }
    }

    if (st.startedByFrost && frostReading.fresh && running() && !cooling() && Number(frostReading.value) >= Number(cfg.frostStop)) {
        serial = stopCommand();
        st.startedByFrost = false;
    }

    const batteryUnavailable = !batteryValue.fresh || !isNumber(batteryValue.voltage);
    const lowVoltage = !batteryUnavailable && Number(batteryValue.voltage) < Number(cfg.lowVoltage);
    if (running() && (batteryUnavailable || lowVoltage)) {
        const since = flow.get('lowSince') || now;
        flow.set('lowSince', since);
        const secondsLeft = Math.max(0, 30 - Math.floor((now - since) / 1000));
        st.warning = (batteryUnavailable ? 'Keine aktuelle Batteriespannung' : 'Unterspannung') + ' – Abschaltung in ' + secondsLeft + ' s';
        if (now - since >= 30000 && !cooling()) {
            serial = stopCommand();
            st.endAt = 0;
            st.warning = (batteryUnavailable ? 'Keine aktuelle Batteriespannung' : 'Unterspannung') + ' – Abschaltung';
        }
    } else {
        flow.set('lowSince', 0);
        if (st.warning && (st.warning.startsWith('Unterspannung') || st.warning.startsWith('Keine aktuelle Batteriespannung'))) st.warning = '';
    }

    if (!serial && effective.fresh && running() && !cooling() && cfg.mode === 'temperature' && st.serialReady) {
        let temperature = Math.max(-50, Math.min(80, Math.round(Number(effective.value))));
        if (temperature < 0) temperature = 256 + temperature;
        serial = sendHex('AA03010011' + temperature.toString(16).padStart(2, '0'));
    }
}

st.cooling = cooling();
st.running = running();
st.startBlocked = canStart(Date.now());

const persistent = {
    cfg,
    lastMaintenanceRun: Number(st.lastMaintenanceRun || 0),
    lastAnnualService: Number(st.lastAnnualService || 0)
};
const persistentJson = JSON.stringify(persistent);
if (flow.get('_autotermPersistentJson') !== persistentJson) {
    try {
        if (persistentStore) flow.set('autotermPersistent', persistent, 'file');
        else flow.set('autotermPersistent', persistent);
    } catch (error) {
        persistentStore = null;
        flow.set('autotermPersistent', persistent);
        st.storageError = String(error.message || error);
    }
    flow.set('_autotermPersistentJson', persistentJson);
}
st.storagePersistent = persistentStore === 'file';
if (st.storagePersistent) delete st.storageError;

flow.set('cfg', cfg);
flow.set('state', st);
return [serial, { payload: { state: st, config: cfg } }];

const buffer = Buffer.isBuffer(msg.payload) ? msg.payload : Buffer.from(msg.payload || []);
const crc = bytes => {
    let value = 0xffff;
    for (const byte of bytes) {
        value ^= byte;
        for (let bit = 0; bit < 8; bit++) value = (value & 1) ? (value >>> 1) ^ 0xa001 : value >>> 1;
    }
    return value;
};
const validPacket = packet => {
    if (packet.length < 7 || packet[0] !== 0xaa) return false;
    const expected = crc(packet.subarray(0, packet.length - 2));
    return packet[packet.length - 2] === ((expected >>> 8) & 0xff) && packet[packet.length - 1] === (expected & 0xff);
};
if (!validPacket(buffer)) {
    node.warn('AUTOTERM-Paket mit ungültiger Struktur oder CRC verworfen');
    return null;
}

const command = buffer[4];
const output = {};
const signed = value => value > 127 ? value - 256 : value;

if (command === 0x0f && buffer.length >= 24) {
    output.statusCode = buffer[5];
    output.subStatus = buffer[6];
    output.error = buffer[7];
    output.internalTemp = signed(buffer[8]);
    output.externalTemp = buffer[9] === 0x7f ? null : signed(buffer[9]);
    output.voltage = buffer[11] / 10;
    output.heaterTemp = buffer[13] - 15;
    output.fanRpm = buffer[17] * 60;
    output.pumpHz = buffer[19] / 100;

    if (output.statusCode === 0) output.status = 'Aus';
    else if (output.statusCode === 1 && output.subStatus === 1) output.status = 'Lüftung';
    else if (output.statusCode === 1) output.status = 'Startet';
    else if (output.statusCode === 2 && output.subStatus >= 2) output.status = 'Zündung';
    else if (output.statusCode === 2) output.status = 'Aufwärmen';
    else if (output.statusCode === 3 && output.subStatus === 35) output.status = 'Lüftung';
    else if (output.statusCode === 3 && output.subStatus === 4) output.status = 'Nachlauf';
    else if (output.statusCode === 3) output.status = 'Heizen';
    else if (output.statusCode === 4) output.status = 'Nachlauf';
    else output.status = 'Status ' + output.statusCode + '.' + output.subStatus;
} else if (command === 0x06 && buffer.length >= 9) {
    output.version = [buffer[5], buffer[6], buffer[7], buffer[8]].join('.');
} else {
    return null;
}

msg.topic = 'heater';
msg.payload = output;
return msg;

const SEEDED_IPS = ['172.24.24.12'];
const STALE_MS = 90000;
const SCAN_INTERVAL_MS = 120000;
const validIp = value => {
    const ip = String(value || '').trim();
    const parts = ip.split('.');
    return parts.length === 4 && parts.every(part => /^\d{1,3}$/.test(part) && Number(part) <= 255) ? ip : '';
};
const loadRegistry = () => {
    const registry = flow.get('indevoltRegistry') || {};
    const add = (ip, source) => {
        ip = validIp(ip);
        if (!ip) return;
        registry[ip] = Object.assign({ ip, serial: '', firmware: '', openData: '', source, firstSeen: Date.now(), lastSeen: 0, online: false, status: 'Warte auf Antwort', error: '' }, registry[ip] || {}, { ip });
    };
    // In diesem Fahrzeug gibt es genau ein INDEVOLT. Die Start-IP darf nur
    // beim leeren Register angelegt werden, sonst erzeugt ein DHCP-Wechsel
    // bei jedem Poll erneut einen Offline-Datensatz.
    if (!Object.keys(registry).length) for (const ip of SEEDED_IPS) add(ip, 'known-network');
    const camperCfg = flow.get('camperConfig') || {};
    if (!Object.keys(registry).length && camperCfg.network && camperCfg.network.indevoltIp) add(camperCfg.network.indevoltIp, 'configured');
    const entries = Object.entries(registry);
    if (entries.length > 1) {
        entries.sort((a, b) => {
            const score = item => (item.online ? 1e15 : 0) + Math.max(Number(item.lastSeen || 0), Number(item.lastDiscovered || 0), Number(item.lastAttempt || 0));
            return score(b[1]) - score(a[1]);
        });
        for (const [duplicateIp] of entries.slice(1)) delete registry[duplicateIp];
    }
    flow.set('indevoltRegistry', registry);
    return registry;
};
const aggregate = registry => {
    const now = Date.now();
    const devices = Object.values(registry).map(item => {
        const online = item.online === true && now - Number(item.lastSeen || 0) <= STALE_MS;
        return Object.assign({}, item, { online, status: online ? (item.status || 'Online') : (item.lastSeen ? 'Offline' : 'Warte auf Antwort') });
    }).sort((a, b) => String(a.serial || a.ip).localeCompare(String(b.serial || b.ip)));
    const active = devices.filter(item => item.online);
    const sum = key => active.some(item => item[key] != null) ? active.reduce((total, item) => total + Number(item[key] || 0), 0) : null;
    const socValues = active.map(item => Number(item.soc)).filter(Number.isFinite);
    const state = {
        online: active.length > 0,
        status: active.length + ' von ' + devices.length + ' online',
        totalCount: devices.length,
        onlineCount: active.length,
        devices,
        soc: socValues.length ? socValues.reduce((a, b) => a + b, 0) / socValues.length : null,
        solarPower: sum('solarPower'),
        batteryPower: sum('batteryPower'),
        acInputPower: sum('acInputPower'),
        acOutputPower: sum('acOutputPower'),
        lastSeen: Math.max(0, ...devices.map(item => Number(item.lastSeen || 0)))
    };
    flow.set('indevoltState', state);
    global.set('camper.indevolt', state);
    return state;
};
const registry = loadRegistry();
const beginScan = () => {
    const scan = flow.get('indevoltScan') || {};
    if (scan.active) return null;
    const next = { active: true, started: Date.now(), token: Date.now().toString(36), results: [], error: '' };
    flow.set('indevoltScan', next);
    flow.set('indevoltLastScan', Date.now());
    return { payload: 'scan', scanToken: next.token };
};
const dashboard = () => ({ payload: { indevolt: aggregate(registry) } });
const requestFor = device => {
    const points = [0, 7101, 6001, 6002, 6000, 1501, 1664, 1665, 2101, 2108];
    return {
        topic: 'indevolt.poll', payload: '', method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        url: 'http://' + device.ip + ':8080/rpc/Indevolt.GetData?config=' + JSON.stringify({ t: points }),
        requestTimeout: 8000, _indevoltIp: device.ip, _indevoltRequestedAt: Date.now()
    };
};

const pollRequested = msg.topic === 'poll' || msg.payload === 'poll' || msg.topic === 'indevolt.discovered' || msg.forcePoll;
if (!pollRequested) return [null, dashboard(), null];
const requests = Object.values(registry).map(requestFor);
const lastScan = Number(flow.get('indevoltLastScan') || 0);
const scanRequest = Date.now() - lastScan >= SCAN_INTERVAL_MS ? beginScan() : null;
return [requests.length ? requests : null, dashboard(), scanRequest];

const STALE_MS = 90000;
const registry = flow.get('indevoltRegistry') || {};
const ip = String(msg._indevoltIp || '').trim();
if (!ip) return null;
const previous = registry[ip] || { ip, serial: '', firstSeen: Date.now(), lastSeen: 0 };
let payload = msg.payload;
if (typeof payload === 'string') {
    try { payload = JSON.parse(payload); } catch (error) { payload = null; }
}
const number = key => payload && payload[key] !== null && payload[key] !== '' && typeof payload[key] !== 'undefined' && Number.isFinite(Number(payload[key])) ? Number(payload[key]) : null;
if (!payload || typeof payload !== 'object' || Number(msg.statusCode || 200) >= 400 || msg.error) {
    registry[ip] = Object.assign({}, previous, { online: false, status: 'Offline', error: 'WLAN/API nicht erreichbar', lastAttempt: Date.now() });
} else {
    const modeMap = { 0: 'Outdoor / mobil', 1: 'Eigenverbrauch', 4: 'Echtzeitsteuerung', 5: 'Zeitplan' };
    const batteryMap = { 1000: 'Bereit', 1001: 'Lädt', 1002: 'Entlädt' };
    const pv1 = number('1664');
    const pv2 = number('1665');
