            voltage: heater.voltage == null ? null : Number(heater.voltage),
            fanRpm: heater.fanRpm == null ? null : Number(heater.fanRpm),
            pumpHz: heater.pumpHz == null ? null : Number(heater.pumpHz),
            effectiveSensor: heater.effectiveSensor || '',
            sensorOnline: heater.sensorOnline === true,
