            charging: Number(sensor('multiplus.dcPower', 0)) > 0 && shoreConnected,
            alarms: { overload: multiAlarmOverload, temperature: multiAlarmTemperature, lowVoltage: multiAlarmLowVoltage },
            online: multiOnline
        },
        starpowerOnline: Object.values(starpower.channels || {}).some(item => now - Number(item.seen || 0) <= staleMs),
        starpowerNames: starpowerCfg.names || [],
        dcChannels,
        starlink: {
