            online: starlinkOnline,
            status: !starlinkPowered ? 'Ausgeschaltet' : (starlinkOnline ? (starlink.status || 'Online') : (starlink.status || 'Lokale API nicht erreichbar')),
            hardwareVersion: starlinkPowered ? (starlink.hardwareVersion || '') : '',
            softwareVersion: starlinkPowered ? (starlink.softwareVersion || '') : '',
            disablementCode: starlinkPowered ? (starlink.disablementCode || 'UNKNOWN') : 'UNKNOWN',
            stowed: starlinkPowered ? starlink.stowed === true : false,
            alerts: starlinkPowered && Array.isArray(starlink.alerts) ? starlink.alerts : [],
