    }
};

const lastCommandFor = target => commands.slice().reverse().find(item => item.target === target && item.completedAt) || null;
let deviceStats = flow.get('camperDeviceStats') || {};
const deviceInput = [
    ['battery', cfg.devices.batteryName, Math.max(seen('battery.soc'), seen('battery.voltage'))],
    ['solar', cfg.devices.solarName, seen('solar.total.power')],
    ['orion', 'Orion XS 12/12-50A', orionSeen],
      ['shellyGrid', 'INDEVOLT Stromzufuhr', shellyGridSeen],
    ['indevolt', cfg.devices.indevoltName, Number(indevolt.lastSeen || 0)],
    ['starpower', 'Safiery STAR-Power', Math.max(0, ...Object.values(starpower.channels || {}).map(item => Number(item.seen || 0)))],
    ['heater', cfg.devices.heaterName, Number(heater.heaterSeen || 0)],
    ['maxxfan', cfg.devices.fanName, Number(adapterFan.seen || 0)],
    ['inverter', cfg.devices.inverterName, Math.max(seen('multiplus.mode'), seen('multiplus.state'))],
    ['water', 'Wassertanks', Math.max(seen('water.fresh.level'), seen('water.waste.level'))]
];
const devices = deviceInput.map(item => {
    const online = now - item[2] <= staleMs;
    const previous = deviceStats[item[0]] || { online, disconnects: 0, reconnects: 0, since: now };
    if (previous.online !== online) {
        if (online) previous.reconnects = Number(previous.reconnects || 0) + 1;
        else previous.disconnects = Number(previous.disconnects || 0) + 1;
        previous.since = now;
        previous.online = online;
        addEvent(online ? 'info' : 'warning', item[0], online ? 'device-online' : 'device-offline', item[1] + (online ? ' wieder verbunden' : ' Verbindung verloren'), item[0]);
    }
    previous.lastSeen = item[2];
    deviceStats[item[0]] = previous;
    const lastCommand = lastCommandFor(item[0] === 'inverter' ? 'inverter' : item[0] === 'maxxfan' ? 'maxxfan' : item[0] === 'heater' ? 'heater' : item[0] === 'starpower' ? 'starpower' : '');
    return { id: item[0], name: item[1], online, lastSeen: item[2], stateSince: previous.since, disconnects: previous.disconnects, reconnects: previous.reconnects, lastCommandDurationMs: lastCommand ? lastCommand.durationMs : null, lastCommandStatus: lastCommand ? lastCommand.status : '' };
});
flow.set('camperDeviceStats', deviceStats);

let history = flow.get('camperHistory');
if (!history || !Array.isArray(history.minute)) {
    try { history = flow.get('camperHistory', 'file') || {}; }
    catch (error) { history = {}; }
}
history.minute = Array.isArray(history.minute) ? history.minute : [];
history.quarterHour = Array.isArray(history.quarterHour) ? history.quarterHour : [];
history.daily = Array.isArray(history.daily) ? history.daily : [];
const historyPoint = { timestamp: now, batterySoc, batteryVoltage, batteryPower: sensor('battery.power'), solarPower: snapshot.energy.totalSolarPower, freshLevel, wasteLevel, roomTemperature: snapshot.climate.roomTemperature, inverterPower: snapshot.power.inverter.outputPower, yieldTodayKwh: snapshot.energy.solar.yieldTodayKwh };
let historyChanged = false;
const sample = (list, period, keepMs) => {
    const bucket = Math.floor(now / period);
    const previous = list[list.length - 1];
    if (!previous || Math.floor(previous.timestamp / period) !== bucket) { list.push(historyPoint); historyChanged = true; }
    const minimum = now - keepMs;
    while (list.length && list[0].timestamp < minimum) { list.shift(); historyChanged = true; }
};
sample(history.minute, 60000, Number(cfg.history.minuteHours || 48) * 3600000);
sample(history.quarterHour, 900000, Number(cfg.history.quarterDays || 90) * 86400000);
sample(history.daily, 86400000, Number(cfg.history.dailyDays || 730) * 86400000);
flow.set('camperHistory', history);

const pointBefore = milliseconds => {
    const wanted = now - milliseconds;
    let selected = null;
    for (const point of history.minute) { if (point.timestamp <= wanted) selected = point; else break; }
    return selected;
};
const oneHour = pointBefore(3600000);
const recentSolar = history.minute.filter(point => point.timestamp >= now - 900000 && Number.isFinite(Number(point.solarPower)));
const solarAverage15m = recentSolar.length ? recentSolar.reduce((sum, point) => sum + Number(point.solarPower), 0) / recentSolar.length : null;
let dailyWaterUse = [];
for (let index = 1; index < history.daily.length; index++) {
    const drop = Number(history.daily[index - 1].freshLevel) - Number(history.daily[index].freshLevel);
    if (Number.isFinite(drop) && drop > 0 && drop < 80) dailyWaterUse.push(drop);
}
dailyWaterUse = dailyWaterUse.slice(-14);
const averageWaterUse = dailyWaterUse.length ? dailyWaterUse.reduce((sum, value) => sum + value, 0) / dailyWaterUse.length : null;

const maintenance = (cfg.maintenance || []).map(task => {
    const dueAt = task.lastDoneAt ? Number(task.lastDoneAt) + Number(task.intervalDays) * 86400000 : 0;
    return Object.assign({}, task, { dueAt, due: dueAt > 0 && dueAt <= now, neverDone: !task.lastDoneAt });
});
snapshot.operations = {
    commands: { pendingCount: commands.filter(item => item.status === 'pending').length, failedCount: commands.filter(item => item.status === 'timeout').length, recent: commands.slice(-10).reverse() },
    events: { unacknowledgedCount: events.filter(item => !item.acknowledgedAt && ['warning', 'critical'].includes(item.level)).length, recent: events.slice(-12).reverse() },
    scenes: (cfg.scenes || []).filter(scene => scene.visible !== false).map(scene => ({ id: scene.id, name: scene.name, icon: scene.icon, actionCount: (scene.actions || []).length })),
    devices,
    maintenance,
    history: {
        samples: { minute: history.minute.length, quarterHour: history.quarterHour.length, daily: history.daily.length },
        // The complete time series remains available from /camper/api/v2/history.
        // Only the 6-hour preview required by the dashboard is carried in each
        // live snapshot. This avoids serialising almost 20 kB every refresh.
        recent: history.quarterHour.slice(-24),
        forecast: {
            batteryTimeToGoSeconds: snapshot.energy.battery.timeToGoSeconds,
            batterySocChange1h: oneHour && batterySoc != null && oneHour.batterySoc != null ? batterySoc - Number(oneHour.batterySoc) : null,
            solarAverage15m,
            freshWaterDays: averageWaterUse && freshLevel != null ? Number(freshLevel) / averageWaterUse : null,
            averageFreshWaterUsePercentPerDay: averageWaterUse
        }
    }
};

if (eventsChanged) {
    events = events.slice(-500);
    flow.set('camperEvents', events);
    try { flow.set('camperEvents', events, 'file'); } catch (error) {}
}
if (historyChanged) {
    try { flow.set('camperHistory', history, 'file'); } catch (error) {}
}

flow.set('camperSequence', snapshot.sequence);
flow.set('camperSnapshot', snapshot);
global.set('camper.snapshot', snapshot);

const clients = flow.get('camperWsClients') || {};
const messages = [];
for (const [id, client] of Object.entries(clients)) {
    if (!client || now - Number(client.lastSeen || 0) > 65000) {
        delete clients[id];
        continue;
    }
    messages.push({ _session: client.session, payload: JSON.stringify({ type: 'state', data: snapshot }) });
}
flow.set('camperWsClients', clients);
return [{ payload: snapshot }, messages];

const topic = String(msg.topic || '');
if (!/^(battery|solar|water|inverter|multiplus|vehicle|orion|shelly)\./.test(topic)) return null;
const raw = msg.payload && typeof msg.payload === 'object' && Object.prototype.hasOwnProperty.call(msg.payload, 'value') ? msg.payload.value : msg.payload;
const value = Number(raw);
if (!Number.isFinite(value)) return null;
const sensors = flow.get('camperSensors') || {};
sensors[topic] = { value, seen: Number(msg._camperSeen || Date.now()) };
flow.set('camperSensors', sensors);
return { topic: 'tick' };

const allowed = ['maxxfan.state', 'water.fresh.state', 'water.waste.state'];
if (!allowed.includes(String(msg.topic || ''))) return null;
const adapters = flow.get('camperAdapters') || {};
const payload = msg.payload && typeof msg.payload === 'object' ? msg.payload : { value: msg.payload };
adapters[msg.topic] = Object.assign({}, payload, { seen: Date.now() });
flow.set('camperAdapters', adapters);
return { topic: 'tick' };

const request = msg.payload && typeof msg.payload === 'object' ? msg.payload : {};
const action = String(request.action || '');
let command = null;

if (action === 'set' && typeof request.value === 'boolean') {
    command = { command: 'active', value: request.value };
} else if (action === 'speed' && Number.isFinite(Number(request.value))) {
    const percent = Math.max(0, Math.min(100, Number(request.value)));
    command = percent <= 0
        ? { command: 'active', value: false }
        : { command: 'speed', value: Math.max(1, Math.min(10, Math.round(percent / 10))) };
} else if (action === 'mode') {
    const requested = String(request.value || '').toLowerCase();
    const current = ((flow.get('camperAdapters') || {})['maxxfan.state'] || {}).mode;
    if (['forward', 'reverse'].includes(requested) && current === requested) return null;
    command = { command: 'direction', value: 1 };
} else if (action === 'lid') {
    command = { command: 'openclose' };
} else if (action === 'auto') {
    command = { command: 'hold', value: request.value === true || Number(request.value) === 1 };
} else {
    node.warn('VanTurtle: nicht unterstützter MaxxFan-Befehl ' + action);
    return null;
}

msg.payload = JSON.stringify(command);
return msg;

let state = msg.payload;
if (Buffer.isBuffer(state)) state = state.toString('utf8');
if (typeof state === 'string') {
    try { state = JSON.parse(state); }
    catch (error) { node.warn('VanTurtle: ungültiger WebSocket-Frame'); return null; }
}
if (!state || typeof state !== 'object' || state.type === 'log') return null;
if (typeof state.active !== 'boolean' || !Number.isFinite(Number(state.speed))) return null;

const speedStep = Math.max(1, Math.min(10, Math.round(Number(state.speed))));
const direction = Number(state.direction) === 1 ? 1 : 0;
const adapters = flow.get('camperAdapters') || {};
adapters['maxxfan.state'] = {
    on: state.active,
    speed: state.active ? speedStep * 10 : 0,
    speedStep,
    direction,
    mode: direction === 1 ? 'reverse' : 'forward',
    autoHold: state.auto_hold === true || Number(state.auto_hold) === 1,
    voltage: Number.isFinite(Number(state.voltage)) ? Number(state.voltage) : null,
    current: Number.isFinite(Number(state.current)) ? Number(state.current) : null,
    power: Number.isFinite(Number(state.power)) ? Number(state.power) : null,
    calibrated: state.has_calibration === true,
    calibrating: state.is_calibrating === true,
    seen: Date.now()
};
flow.set('camperAdapters', adapters);
return { topic: 'tick' };

const WHITE_CHANNEL = 7;
const WARNING_CHANNEL = 8;
const INTERVAL_MS = 500;
let warning = flow.get('frontWarningBlink') || {
    active: false, phase: false, pending: false,
    intervalMs: INTERVAL_MS, startedAt: 0, lastCommandAt: 0, lastAckAt: 0
};
const physical = (channel, value) => ({
    topic: 'ui',
    payload: { action: 'toggle', channel, value, _warningPhysical: true }
});
const stopTimer = () => {
    const timer = context.get('blinkTimer');
    if (timer) clearTimeout(timer);
    context.set('blinkTimer', null);
};
const scheduleNextEdge = () => {
    stopTimer();
    if (!warning.active || warning.pending) return;
    const timer = setTimeout(() => {
        context.set('blinkTimer', null);
        const current = flow.get('frontWarningBlink') || {};
        if (current.active !== true || current.pending === true) return;
        current.phase = current.phase !== true;
        current.pending = true;
        current.lastCommandAt = Date.now();
        flow.set('frontWarningBlink', current);
        // Genau ein physischer Pfad: STAR-Power CH 8 State.
        node.send(physical(WARNING_CHANNEL, current.phase ? 1 : 0));
    }, INTERVAL_MS);
    context.set('blinkTimer', timer);
};

if (msg.topic === 'front-warning-reset') {
    stopTimer();
    warning = {
        active: false, phase: false, pending: false,
        intervalMs: INTERVAL_MS, startedAt: 0,
        lastCommandAt: Date.now(), lastAckAt: 0
    };
    flow.set('frontWarningBlink', warning);
    // Sicherer Startzustand nur für CH 8; CH 11 bleibt unangetastet.
    return [physical(WARNING_CHANNEL, 0)];
}

if (msg.topic === 'state:8') {
    const feedback = Number(msg.payload);
    const expected = warning.phase ? 1 : 0;
    if (warning.active && warning.pending && (feedback === 0 || feedback === 1) && feedback === expected) {
        warning.pending = false;
        warning.lastAckAt = Date.now();
        flow.set('frontWarningBlink', warning);
        scheduleNextEdge();
    }
    // Rückmeldung zusätzlich an die normale STAR-Power-Auswertung geben.
    return [msg];
}

if (msg.topic !== 'ui' || !msg.payload || typeof msg.payload !== 'object') return [msg];
const action = msg.payload;
const channel = Number(action.channel);

if (action.action === 'toggle' && channel === WARNING_CHANNEL && action._warningPhysical !== true) {
    const enabled = Number(action.value) === 1;
    stopTimer();
    warning.active = enabled;
    warning.phase = enabled;
    warning.pending = enabled;
    warning.startedAt = enabled ? Date.now() : 0;
    warning.lastCommandAt = Date.now();
    flow.set('frontWarningBlink', warning);
    const messages = [];
    if (enabled) messages.push(physical(WHITE_CHANNEL, 0));
    messages.push(physical(WARNING_CHANNEL, enabled ? 1 : 0));
    return [messages];
}

if (action.action === 'toggle' && channel === WHITE_CHANNEL && Number(action.value) === 1 && action._warningPhysical !== true) {
    stopTimer();
    warning.active = false;
    warning.phase = false;
    warning.pending = false;
    warning.startedAt = 0;
    warning.lastCommandAt = Date.now();
    flow.set('frontWarningBlink', warning);
    return [[physical(WARNING_CHANNEL, 0), msg]];
}

// Warnlicht ist absichtlich nicht dimmbar. Auch ein veralteter Client darf
// niemals einen CH-8-Dimming-Befehl oder einen anderen Kanal ansteuern.
if (action.action === 'dim' && channel === WARNING_CHANNEL) return null;
return [msg];

finalize:
const timer = context.get('blinkTimer');
if (timer) clearTimeout(timer);
context.set('blinkTimer', null);

func:
const values = String(msg.payload == null ? '' : msg.payload)
    .split(/\s+/)
    .map(Number)
    .filter(Number.isFinite)
    .map(value => value > 200 ? value / 1000 : value)
    .filter(value => value >= -20 && value <= 150);
if (!values.length) return null;
// Falls das Board mehrere Thermal-Zones meldet, ist die höchste Temperatur
// für die Gehäusebelüftung die sichere Regelgröße.
msg.topic = 'ventilation.cpu';
msg.payload = Math.round(Math.max(...values) * 10) / 10;
return msg;

const cfg = flow.get('camperConfig') || {};
const settings = Object.assign({ enabled: true, manualOn: false, onTemperature: 65, hysteresis: 5 }, cfg.ventilation || {});
let state = flow.get('ventilationState') || {
    active: false,
    manualOn: false,
    supplyOn: false,
    exhaustOn: false,
    supplyFeedback: null,
    exhaustFeedback: null,
    cpuTemperature: null,
    sensorOnline: false,
    reason: 'Initialisierung',
    updatedAt: 0
};

// Reale Verdrahtung: Relais 1 = Abluft, Relais 2 = Zuluft.
if (msg.topic === 'ventilation.relay1') state.exhaustFeedback = Number(msg.payload) === 1;
if (msg.topic === 'ventilation.relay2') state.supplyFeedback = Number(msg.payload) === 1;

if (msg.topic === 'ventilation.cpu' && Number.isFinite(Number(msg.payload))) {
    state.cpuTemperature = Number(msg.payload);
    state.cpuSeen = Date.now();
}

const temperature = Number(state.cpuTemperature);
const sensorValid = Number.isFinite(temperature) && Date.now() - Number(state.cpuSeen || 0) < 30000;
state.sensorOnline = sensorValid;
state.sensorName = 'Cerbo GX CPU';
const onTemperature = Math.max(30, Math.min(95, Number(settings.onTemperature || 65)));
const hysteresis = Math.max(2, Math.min(20, Number(settings.hysteresis || 5)));
const manualOn = settings.manualOn === true;
let desired = state.active === true;

if (manualOn) {
    desired = true;
    state.reason = 'Manuell eingeschaltet';
} else if (settings.enabled !== true) {
    desired = false;
    state.reason = 'Automatik aus';
} else if (!sensorValid) {
    // Ohne aktuelle Temperatur schaltet nur der bewusste Handbetrieb ein.
    desired = false;
    state.reason = 'CPU-Temperatur nicht verfügbar';
} else if (desired && temperature <= onTemperature - hysteresis) {
    desired = false;
    state.reason = 'Unter Ausschalttemperatur';
} else if (!desired && temperature >= onTemperature) {
    desired = true;
    state.reason = 'CPU-Temperatur zu hoch';
} else {
    state.reason = desired ? 'Temperatur halten · Lüftung läuft' : 'Temperatur im Sollbereich';
}

const changed = state.active !== desired || state.supplyOn !== desired || state.exhaustOn !== desired;
state.active = desired;
state.manualOn = manualOn;
state.supplyOn = desired;
state.exhaustOn = desired;
state.enabled = settings.enabled === true;
state.onTemperature = onTemperature;
state.offTemperature = onTemperature - hysteresis;
state.hysteresis = hysteresis;
state.updatedAt = Date.now();
flow.set('ventilationState', state);

const relay1 = state.exhaustFeedback === desired && !changed ? null : { payload: desired ? 1 : 0 };
const relay2 = state.supplyFeedback === desired && !changed ? null : { payload: desired ? 1 : 0 };
const refresh = changed || msg.topic === 'ventilation.relay1' || msg.topic === 'ventilation.relay2'
    ? { topic: 'tick', _camperSource: 'ventilation' }
    : null;
return [relay1, relay2, refresh];

const cfg = flow.get('camperConfig') || {};
const settings = Object.assign({ enabled: false, mode: 'auto', targetTemperature: 22, hysteresis: 1, fanSpeed: 50 }, cfg.climateAutomation || {});
const heater = flow.get('state') || {};
const fan = ((flow.get('camperAdapters') || {})['maxxfan.state']) || {};
let state = flow.get('climateAutomationState') || {
    demand: 'idle', heaterOwned: false, fanOwned: false,
    roomTemperature: null, ceilingTemperature: null, sensorOnline: false, reason: 'Automatik aus', updatedAt: 0
};

if (msg.payload && msg.payload.state) {
    const sourceState = msg.payload.state;
    const sensors = sourceState.sensors || {};
    const fresh = item => item && Number.isFinite(Number(item.temp)) && Date.now() - Number(item.seen || 0) < 180000;
    const comfort = fresh(sensors.ruuvi3) ? sensors.ruuvi3 : null;
    const ceiling = fresh(sensors.ruuvi1) ? sensors.ruuvi1 : null;
    state.roomTemperature = comfort ? Number(comfort.temp) : (sourceState.roomTemp == null ? null : Number(sourceState.roomTemp));
    state.ceilingTemperature = ceiling ? Number(ceiling.temp) : null;
    state.sensorOnline = Number.isFinite(state.roomTemperature);
    state.sensorName = comfort ? String(comfort.label || 'Komfortmittel') : String(sourceState.effectiveSensor || 'Regelsensor');
}

const heatingTemperature = Number(state.roomTemperature);
const coolingTemperature = Number.isFinite(Number(state.ceilingTemperature)) ? Number(state.ceilingTemperature) : heatingTemperature;
const target = Math.max(10, Math.min(30, Number(settings.targetTemperature || 22)));
const hysteresis = Math.max(0.5, Math.min(5, Number(settings.hysteresis || 1)));
const fanSpeed = Math.max(10, Math.min(100, Math.round(Number(settings.fanSpeed || 50) / 10) * 10));
const sensorValid = state.sensorOnline === true && Number.isFinite(heatingTemperature);
const previousDemand = state.demand || 'idle';
let demand = previousDemand;

if (settings.enabled !== true) {
    demand = 'idle';
    state.reason = 'Klimaautomatik aus';
} else if (!sensorValid) {
    demand = 'idle';
    state.reason = 'Temperatursensor nicht verfügbar';
} else {
